const listActiveSecretLeasesForBot = `-- name: ListActiveSecretLeasesForBot :many
SELECT id, workspace_id, bot_id, secret_request_id, turn_id, conversation_id, adapter_id, domain_match, port, auth_scheme, header_name, username, placeholder_env, placeholder_value, kek_id, wrapped_dek, encrypted_value, expires_at, revoked_at, revocation_reason, created_by, created_at
FROM secret_leases
WHERE workspace_id = $1
  AND bot_id = $2
  AND revoked_at IS NULL
  AND expires_at > $3::timestamptz
ORDER BY created_at DESC
`

type ListActiveSecretLeasesForBotParams struct {
	WorkspaceID pgtype.UUID        `json:"workspace_id"`
	BotID       pgtype.UUID        `json:"bot_id"`
	AsOf        pgtype.Timestamptz `json:"as_of"`
}

func (q *Queries) ListActiveSecretLeasesForBot(ctx context.Context, arg ListActiveSecretLeasesForBotParams) ([]SecretLease, error) {
	rows, err := q.db.Query(ctx, listActiveSecretLeasesForBot, arg.WorkspaceID, arg.BotID, arg.AsOf)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SecretLease
	for rows.Next() {
		var i SecretLease
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.BotID,
			&i.SecretRequestID,
			&i.TurnID,
			&i.ConversationID,
			&i.AdapterID,
			&i.DomainMatch,
			&i.Port,
			&i.AuthScheme,
			&i.HeaderName,
			&i.Username,
			&i.PlaceholderEnv,
			&i.PlaceholderValue,
			&i.KekID,
			&i.WrappedDek,
			&i.EncryptedValue,
			&i.ExpiresAt,
			&i.RevokedAt,
			&i.RevocationReason,
			&i.CreatedBy,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

